import{_ as l,o as a,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2020-05-27 :: Ceph Science User Group Meeting","description":"","frontmatter":{"title":"2020-05-27 :: Ceph Science User Group Meeting","date":"2020-05-27T00:00:00.000Z","updated":"2020-05-29T00:00:00.000Z","tags":["Ceph","分布式存储","故障与解决方案","集群管理","容器化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-05-27_-_-_Ceph_Science_User_Group_Meeting.md","filePath":"posts/2020/2020-05-27_-_-_Ceph_Science_User_Group_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2020/2020-05-27_-_-_Ceph_Science_User_Group_Meeting.md"};function o(n,e,s,p,_,h){return a(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次会议是非正式的讨论会，主要围绕Ceph的科学研究、大型集群以及与Ceph相关的各种话题展开。会议鼓励参与者自由发言，分享经验和技术问题。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>近期故障和解决方案</strong></p><ul><li>讨论了马里兰大学在NVMe驱动器上遇到的数据库日志和数据分区问题，以及MDS崩溃导致的服务中断。</li><li>介绍了通过减少MDS缓存大小来解决问题的方法。</li></ul></li><li><p><strong>硬件扩展和集群管理</strong></p><ul><li>讨论了在扩展集群时遇到的性能问题，特别是在添加新硬件后数据重新平衡的问题。</li><li>讨论了使用CRUSH map和upmap工具管理数据分布的挑战和限制。</li></ul></li><li><p><strong>Ceph版本升级和性能</strong></p><ul><li>分享了从Luminous升级到Octopus的经验，以及升级过程中遇到的性能优化和问题。</li><li>讨论了Ceph的Telemetry模块可能导致集群进入警告模式的问题。</li></ul></li><li><p><strong>容器化和Ceph的未来</strong></p><ul><li>讨论了Ceph与容器技术（如Docker）的集成，以及这对未来部署和管理的影响。</li><li>表达了对容器化可能带来的性能影响和复杂性的担忧。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>计划在7月22日举行下一次会议，并发送提醒通知。</li><li>建议参与者添加他们的联系信息和集群配置，以便更好地匹配和交流。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续关注和讨论Ceph的最新版本和功能，特别是Octopus的升级和使用经验。</li><li>探索和测试Ceph与容器技术的集成，评估其对性能和管理的影响。</li><li>收集和分享集群配置和使用经验，以便更好地理解和解决共同面临的问题。</li></ul><h4 id="其他备注" tabindex="-1">其他备注 <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注&quot;">​</a></h4><ul><li>鼓励新参与者加入，并提供了联系方式以便未来邀请。</li><li>主持人感谢所有参与者的贡献，并期待在下次会议中再次交流。</li></ul>',11)])])}const d=l(r,[["render",o]]);export{c as __pageData,d as default};
